public class StacklessException extends RuntimeException {

    @Override
    public synchronized Throwable fillInStackTrace() {
        return this;  // NO stack capture! FAST!
    }

    // Singleton for zero-allocation throws:
    public static final StacklessException INVALID_AMOUNT =
        new StacklessException("Amount must be positive");
    public static final StacklessException INVALID_SYMBOL =
        new StacklessException("Symbol is required");

    public StacklessException(String message) { super(message); }
}
