// ─── File: src/test/java/com/bank/stackless/StacklessTest.java ───
package com.bank.stackless;

import com.bank.stackless.exception.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class StacklessTest {

    @Test
    void normalException_hasStackTrace() {
        try {
            throw new NormalException("test");
        } catch (NormalException e) {
            assertThat(e.getStackTrace()).isNotEmpty();
            assertThat(e.getStackTrace()[0].getMethodName())
                .isEqualTo("normalException_hasStackTrace");
        }
    }

    @Test
    void stacklessException_emptyStackTrace() {
        try {
            throw new StacklessException("test");
        } catch (StacklessException e) {
            assertThat(e.getStackTrace()).isEmpty();  // NO stack trace!
            // getMessage() still works:
            assertThat(e.getMessage()).isEqualTo("test");
        }
    }

    @Test
    void singleton_zeroAllocation() {
        try {
            throw StacklessException.INVALID_AMOUNT;
        } catch (StacklessException e) {
            assertThat(e.getMessage()).isEqualTo("Amount must be positive");
            assertThat(e.getStackTrace()).isEmpty();
            // Same object thrown every time — zero allocation per throw!
        }
    }

    @Test
    void performanceComparison() {
        int iterations = 100_000;

        // Normal: with stack trace
        long normalStart = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            try { throw new NormalException("x"); } catch (NormalException e) { }
        }
        long normalTime = (System.nanoTime() - normalStart) / 1_000_000;

        // Stackless: no stack trace
        long stacklessStart = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            try { throw StacklessException.INVALID_AMOUNT; } catch (StacklessException e) { }
        }
        long stacklessTime = (System.nanoTime() - stacklessStart) / 1_000_000;

        System.out.println("Normal: " + normalTime + "ms, Stackless: " + stacklessTime + "ms");
        // Typical: Normal ~150ms, Stackless ~2ms → ~75x faster!
        assertThat(stacklessTime).isLessThan(normalTime);
    }
}
